-- BE-INCR-NFCE PR-4 (nó X10a, EMENDA-3 F-NFCE-E3-2 a, ratificado 17/10; executa: dono, chat, 2026-10-26 "faz o X10a EMENDA-2
-- PR-1..PR-6 e EMENDA-3 (#757)"). Só dado: tabela INUT_NAO_SE_APLICA — a UF (IBGE no discriminador) onde o pedido de
-- inutilização "não se aplica" desde 01/11/2026, por tipo (chave NFE = Aj. SINIEF 40/26; NFCE = Aj. SINIEF 38/26). É o
-- aviso da lista de lacunas, não uma recusa: com o E3-1 (c) o pedido segue para a SEFAZ. Os INSERTs são o texto de
-- prisma/data/legal_parameters_inut_nao_se_aplica_v1.sql (teste-guarda de igualdade). INSERT OR IGNORE com id fixo: retomável.
INSERT OR IGNORE INTO "legal_parameters" ("id","tabela","chave","discriminador","valorInt","valorTexto","valorJson","fonte","fonteUrl","fonteSha256","vigenteDesde","vigenteAte","status","supersedesId","motivo","proposedById","publishedById","publishedAt","createdAt") VALUES ('lp-inut-nao-se-aplica-nfe-ac', 'INUT_NAO_SE_APLICA', 'NFE', '12', NULL, 'o Aj. SINIEF 40/26 (NF-e) diz que o pedido de inutilização não se aplica a esta UF desde 01/11/2026; o pedido pode ser enviado e a SEFAZ decide; ver com o contador', NULL, 'Ajuste SINIEF 07/05 cl. 14ª § 6º, acrescido pelo Ajuste SINIEF 40/26 cl. 2ª II (efeitos a partir de 01.11.26): "O Pedido de Inutilização de Número da NF-e previsto no "caput" não se aplica aos Estados do Acre, Bahia e São Paulo"', 'https://www.confaz.fazenda.gov.br/legislacao/ajustes/2005/AJ007_05', 'f44adf45f3e22df040e5dc588c5aa5d944b0a7a468ea90adecc000e405843670', '2026-11-01', NULL, 'PUBLISHED', NULL, 'BE-INCR-NFCE PR-4 (nó X10a, EMENDA-3 F-NFCE-E3-2 a; D-2026-10-26-X10A-EXECUCAO): aviso nas lacunas de numeração; texto vigente lido no compilado do CONFAZ (dossiês sp-inutilizacao-nfe-nfce-2026-11 [D01]/[D02], 17/10/2026, e x10a-pr0-leiaute-saida, 26/10/2026 — mesmo SHA-256); início = cl. 3ª dos Aj. 38/26 e 40/26 (DOU 14/09/2026)', 'migracao:X10A-PR4', 'migracao:X10A-PR4', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
